from pydantic import BaseModel, Field
from typing import List, Optional


class Node(BaseModel):
    id: str
    title: str
    description: str
    prerequisites: List[str] = Field(default_factory=list)

    class Config:
        # Node details are generated by the roadmap service and rendered by
        # the client. Preserve them when saving rather than stripping fields
        # that are not part of this minimal validation contract.
        extra = "allow"


class Edge(BaseModel):
    source: str
    target: str

    class Config:
        extra = "allow"


class Roadmap(BaseModel):
    title: str
    description: str
    nodes: List[Node]
    edges: List[Edge]
    user_id: Optional[str] = None  # Optional if user-based saving is added

    class Config:
        extra = "allow"
